    w=0
    for ch in s:
        o=ord(ch)
        if o<32 or o==127:
            continue
        if unicodedata.combining(ch):
            continue
        cat=unicodedata.category(ch)
        if cat in ('Mn','Me','Cf'):
            continue
        if unicodedata.east_asian_width(ch) in ('W','F'):
            w+=2
        else:
            w+=1
    return w

