    s=val_str
    orig=s
    if s.startswith('+'):
        digits=s[1:]
    else:
        digits=s
    if digits=='' or not all('0'<=c<='9' for c in digits):
        raise CliError(f"Could not deserialize '{orig}' to u64 for '{display}'.".encode())
    try:
        v=int(digits)
    except:
        raise CliError(f"Could not deserialize '{orig}' to u64 for '{display}'.".encode())
    if v>18446744073709551615:
        raise CliError(f"Could not deserialize '{orig}' to u64 for '{display}'.".encode())
