        self.positionals=[]
        self.counts={}

def parse_subcommand(spec, argv):
    # returns ParsedArgs with typed values (opts values are raw strings or defaults/parsed)
    opts_by_long={}
    opts_by_short={}
    for o in spec.options:
        if o.long: opts_by_long[o.long]=o
        if o.short: opts_by_short[o.short]=o
    # include help always
    help_opt=Opt('h','help',False,'help',kind='bool')
    opts_by_long['help']=help_opt; opts_by_short['h']=help_opt
    all_options=list(spec.options)+[help_opt]
    parsed=ParsedArgs()
    counts={}
    values={}
    positionals=[]
    after_dashes=False
    i=0
    while i<len(argv):
        token=argv[i]
        if after_dashes:
            positionals.append(token); i+=1; continue
        if token=="--":
            after_dashes=True; i+=1; continue
        if token=="-" or token=="" or not token.startswith('-'):
            positionals.append(token); i+=1; continue
        if token.startswith('--'):
            if '=' in token:
                name,val=token.split('=',1)
                o=opts_by_long.get(name[2:])
                if o is None:
                    # unknown flag
                    raise unknown_flag_error(spec, name)
                if not o.takes_arg:
                    raise CliError((f"Flag '{name}' cannot have an argument, but found '{val}'.\n\nUsage:\n"+USAGE_SNIPPETS[spec.name].rstrip('\n')).encode())
                counts[o.dest]=counts.get(o.dest,0)+1; values[o.dest]=val
            else:
                name=token
                o=opts_by_long.get(name[2:])
                if o is None:
                    raise unknown_flag_error(spec, name)
                if not o.takes_arg:
                    counts[o.dest]=counts.get(o.dest,0)+1; values[o.dest]=True
                else:
                    if i+1>=len(argv):
                        raise CliError((f"Expected argument for flag '--{o.long}' but reached end of arguments.\n\nUsage:\n"+USAGE_SNIPPETS[spec.name].rstrip('\n')).encode())
                    counts[o.dest]=counts.get(o.dest,0)+1; values[o.dest]=argv[i+1]; i+=1
            i+=1; continue
        else:
            # short group
            j=1
            consumed_next=False
            while j<len(token):
                c=token[j]
                o=opts_by_short.get(c)
                if o is None:
                    raise unknown_flag_error(spec, '-'+c)
                if not o.takes_arg:
                    counts[o.dest]=counts.get(o.dest,0)+1; values[o.dest]=True; j+=1; continue
                else:
                    rest=token[j+1:]
                    if rest!='':
                        counts[o.dest]=counts.get(o.dest,0)+1; values[o.dest]=rest
                    else:
                        if i+1>=len(argv):
                            raise CliError((f"Expected argument for flag '--{o.long}' but reached end of arguments.\n\nUsage:\n"+USAGE_SNIPPETS[spec.name].rstrip('\n')).encode())
                        counts[o.dest]=counts.get(o.dest,0)+1; values[o.dest]=argv[i+1]; consumed_next=True
                    j=len(token)
            if consumed_next: i+=1
            i+=1; continue
    parsed.positionals=positionals
    parsed.counts=counts
    # defaults
    result={}
    for o in all_options:
        if o.dest in values:
            result[o.dest]=values[o.dest]
        else:
            if o.takes_arg:
                result[o.dest]=o.default
            else:
                result[o.dest]=False
    parsed.opts=result
    # validate duplicates & positionals
    duplicate = any(c>1 for c in counts.values())
    valid_pos = spec.positional_validator(positionals, result.get('help', False))
    if duplicate or not valid_pos:
        raise usage_error(spec.name, "Invalid arguments.")
    if result.get('help'):
        sys.stdout.buffer.write(HELP_TEXTS[spec.name].encode())
        raise SystemExit(0)
    # conversions in specified order
    # map dest->opt
    optmap={o.dest:o for o in all_options}
    for dest in spec.convert_order:
        o=optmap.get(dest)
        if o is None: continue
        val=result.get(dest)
        if val is None: continue
        if o.kind=='u64':
            result[dest]=parse_u64_value(val, o.label or ('--'+o.long))
        elif o.kind=='delim':
            result[dest]=parse_single_ascii(val)
