                self.i += 2; self.line += 1; self.prev_term_crlf=True
            else:
                self.i += 1; self.prev_term_crlf=False
        else: # \n
            self.i += 1; self.line += 1; self.prev_term_crlf=False

    def _next_raw(self):
        data=self.data; n=self.n
