        while True:
            if self.i>=n:
                return None
            c=data[self.i]
            if c==10 or c==13:
                self._consume_terminator()
                continue
            break
        start_actual=self.i
        if self.record_counter==0 and self._bom:
            report_byte=0
        else:
            report_byte=start_actual-1 if self.prev_term_crlf else start_actual
        report_line=self.line-1 if self.prev_term_crlf else self.line
        if report_line<1: report_line=1
        rec_index=self.record_counter
        fields=[]
        # parse fields loop
        while True:
            field=bytearray()
            if self.i>=n:
                # empty trailing field at EOF
                fields.append(bytes(field))
                break
            # field start
            if self.quoting and data[self.i]==self.quote:
                # quoted
                self.i += 1
                closed=False
                while self.i<n:
                    ch=data[self.i]
                    if self.escape is not None and ch==self.escape:
                        if self.i+1<n:
                            nxt=data[self.i+1]
                            field.append(nxt)
