        if self.expected_len is None:
            self.expected_len=len(fields)
        elif not self.flexible and len(fields)!=self.expected_len:
            raise CliError(f"CSV error: record {rec_index} (line: {report_line}, byte: {report_byte}): found record with {len(fields)} fields, but the previous record has {self.expected_len} fields".encode())
