                w=display_width(cell)
                if w>widths[idx]: widths[idx]=w
        for cells in self.block:
            out=bytearray()
            for idx, cell in enumerate(cells):
                out.extend(cell)
                if idx < len(cells)-1:
                    colw=max(self.minwidth, widths[idx])+self.padding
                    pad=colw-display_width(cell)
                    if pad>0: out.extend(b' '*pad)
            out.extend(b'\n')
            self.stream.write(bytes(out))
