        if self.quote_always:
            return True
        if nfields==1 and len(field)==0:
            return True
        q=self.quote; d=self.delimiter; e=self.escape
        for ch in field:
            if ch==d or ch==q or ch==10 or ch==13:
                return True
            if e is not None and ch==e:
                return True
            if len(self.terminator)==1 and ch==self.terminator[0]:
                return True
        return False

    def _serialize(self, fields):
        if len(fields)==0:
            return bytes([self.quote, self.quote])
        out=bytearray()
        for idx, field in enumerate(fields):
            if idx: out.append(self.delimiter)
            if self._needs_quote(field, len(fields)):
                out.append(self.quote)
                if self.escape is None:
                    # double quotes
                    for ch in field:
                        out.append(ch)
                        if ch==self.quote: out.append(ch)
                else:
                    for ch in field:
                        if ch==self.quote: out.append(self.escape)
                        out.append(ch)
                out.append(self.quote)
            else:
                out.extend(field)
        return bytes(out)

