def display_width(bs):
    # bs: bytes for a cell piece (may contain control chars)
    s=bs.decode('utf-8', 'replace')
    w=0
    for ch in s:
        o=ord(ch)
        if o<32 or o==127:
            continue
        if unicodedata.combining(ch):
            continue
        cat=unicodedata.category(ch)
        if cat in ('Mn','Me','Cf'):
            continue
        if unicodedata.east_asian_width(ch) in ('W','F'):
            w+=2
        else:
            w+=1
    return w

def condense_field(field, limit):
    if limit is None:
        return field
    try:
        s=field.decode('utf-8')
        if len(s)>limit:
            return (s[:limit]+"...").encode('utf-8')
        return field
    except UnicodeDecodeError:
        if len(field)>limit:
            return field[:limit]+b'...'
        return field

