                if idx < len(cells)-1:
                    colw=max(self.minwidth, widths[idx])+self.padding
                    pad=colw-display_width(cell)
                    if pad>0: out.extend(b' '*pad)
            out.extend(b'\n')
            self.stream.write(bytes(out))
