            try:
                with open(pb,'rb') as f: self._data=f.read()
            except OSError as e:
                raise CliError(io_error_bytes(e))
        return self._data
    def count_total(self):
        d=self.load()
        if len(d)<8:
            raise CliError(b"Invalid argument (os error 22)")
        return struct.unpack('>Q', d[-8:])[0]
    def offset(self, physical_index):
        d=self.load()
        off=physical_index*8
        if off+8>len(d):
            raise CliError(b"failed to fill whole buffer")
        return struct.unpack('>Q', d[off:off+8])[0]
    def data_count(self, has_headers):
        total=self.count_total()
        if has_headers:
            return total-1 if total>0 else 0
        return total

