def rust_usize_parse_error(content_bytes):
    # returns message suffix for converting bracket content to integer
    if len(content_bytes)==0:
        return "cannot parse integer from empty string"
    s=content_bytes
    # Rust parse::<usize>: optional + then digits
    if s.startswith(b'+'):
        digits=s[1:]
        if len(digits)==0:
            return "invalid digit found in string"
    else:
        digits=s
    if not all(48<=c<=57 for c in digits):
        return "invalid digit found in string"
    v=int(digits.decode())
    if v>18446744073709551615:
        return "number too large to fit in target type"
    return None

def try_usize_token(tok_bytes):
    # returns int or None if parse fails (as Rust fallback to name)
    if len(tok_bytes)==0: return None
    s=tok_bytes
    digits=s[1:] if s.startswith(b'+') else s
    if len(digits)==0: return None
    if not all(48<=c<=57 for c in digits): return None
    v=int(digits.decode())
    if v>18446744073709551615: return None
    return v

