def cmd_partition(args, pos):
    col_str=pos[0]; outdir=pos[1]; path=pos[2] if len(pos)>2 else None
    sel=parse_selection_arg(col_str)
    template=args.get('filename')
    if template is None: template='{}.csv'
    if template.count('{}')!=1:
        err(b"The --filename argument must contain one '{}'.")
    # create outdir
    try:
        os.makedirs(B(outdir), exist_ok=True)
    except OSError as e:
        raise CliError(io_error_bytes(e))
    data=read_input_config(path)
    rdr=get_reader(data,args)
    headers=rdr.headers()
    indices=sel.resolve(headers, args.get('no_headers',False))
    if len(indices)!=1:
        err(b"can only partition on one column")
    colidx=indices[0]
    no_headers=args.get('no_headers',False)
    drop=args.get('drop',False)
    prefix_len=args.get('prefix_length')
    # writers dict key=truncated value bytes -> (writer, stream, filename_assigned)
    writers={}  # key -> CsvWriter
    streams={}
    used_names=set()  # filenames (strings) already assigned
    assigned_filename={}  # key-> filename string
    def sanitize(key_bytes):
        # truncate already done, decode lossy
        s=key_bytes.decode('utf-8','replace')
        out_chars=[]
        for ch in s:
            cat=unicodedata.category(ch)
            if ch=='_' or cat[0] in ('L','M','N'):
                out_chars.append(ch)
        res=''.join(out_chars)
        if res=='':
            res='empty'
        return res
    try:
        for rec in rdr.records():
            key_val=rec[colidx]
            if prefix_len is not None:
                key_trunc=key_val[:prefix_len]
            else:
                key_trunc=key_val
            if key_trunc not in writers:
                base_sanitized=sanitize(key_trunc)
                candidate_sanitized=base_sanitized
                counter=0
                while True:
                    fname=template.replace('{}', candidate_sanitized, 1)
                    if fname not in used_names:
                        break
                    counter+=1
                    candidate_sanitized=f"{base_sanitized}_{counter}"
                used_names.add(fname)
                assigned_filename[key_trunc]=fname
                fullpath=os.path.join(B(outdir), B(fname))
                # create parent dirs? Original partitioned a.b/{}.csv created subdir - attempt to create parent if needed?
                parent=os.path.dirname(fullpath)
                if parent and not os.path.exists(parent):
                    try: os.makedirs(parent, exist_ok=True)
                    except OSError as e: raise CliError(io_error_bytes(e))
                try:
                    stream=open(fullpath,'wb')
                except OSError as e:
                    raise CliError(io_error_bytes(e))
                wtr=CsvWriter(stream, delimiter=args.get('delimiter',44))
                writers[key_trunc]=wtr; streams[key_trunc]=stream
                if not no_headers:
                    hdr=list(headers)
                    if drop:
                        hdr=[h for i,h in enumerate(hdr) if i!=colidx]
                    wtr.write_record(hdr)
            outrec=list(rec)
            if drop:
                outrec=[v for i,v in enumerate(outrec) if i!=colidx]
            writers[key_trunc].write_record(outrec)
    finally:
        for s in streams.values():
            try: s.close()
            except Exception: pass
    return 0

# RNG for sample: placeholder using Python's deterministic Random; will be refined later
class SampleRNG:
    def __init__(self, seed):
        self.seed=seed
        self.state=None
        # minimal xoshiro262? Use random.Random for now
        import random
        self._r=random.Random(seed)
    def rand_range(self, n):
        # return integer in [0,n)
        return self._r.randrange(n)
    def random_indices_choose(self, total, amount):
        # for indexed sampling
        import random
        if self.seed is None:
            r=random.SystemRandom()
        else:
            r=self._r
        # generate distinct indices in generation order
        chosen=[]
        seen=set()
        while len(chosen)<amount:
            v=r.randrange(total)
            if v in seen: continue
            seen.add(v); chosen.append(v)
        return chosen

def get_sample_rng(seed):
    return SampleRNG(seed)

def cmd_sample(args, pos):
    sample_size=args.get('sample_size_parsed')
    path=pos[1] if len(pos)>1 else None
    seed=args.get('seed')
    rng=get_sample_rng(seed)
    # indexed check
    data_idx, idx = maybe_indexed_reader_data(path, args)
    # writer first behaviour: creating output before reading input in original for most paths.
    # We already may have read input via indexed check; for non-indexed, open output before reading input
    # Implement by opening OutCtx first, then reading input if needed.
    with OutCtx(args.get('output')) as stream:
        wtr=CsvWriter(stream, delimiter=args.get('delimiter',44))
        if data_idx is not None:
            data=data_idx
            # total records
            has_headers=not args.get('no_headers',False)
            # Count via index (may error)
            total_data=idx.data_count(has_headers)
            # read headers/records sequentially for reservoir or indexed access
            rdr=get_reader(data,args)
            headers=rdr.headers()
            if not args.get('no_headers',False):
                if len(headers)>0:
                    wtr.write_record(headers)
            if sample_size==0:
                return 0
            # decide indexed path
            if total_data>0 and sample_size < total_data * 0.1:
                # random indexing
                rows=list(rdr.records())
                # rows list length may differ from total_data if file changed; use rows for random retrieval
                indices=rng.random_indices_choose(total_data, sample_size)
                for ix in indices:
                    if 0 <= ix < len(rows):
                        wtr.write_record(rows[ix])
                return 0
            else:
                # reservoir over records
                reservoir=[]
                # need to re-create reader since records consumed? rdr.records not yet consumed except headers ensured
                for i, rec in enumerate(rdr.records()):
                    if i < sample_size:
                        reservoir.append(rec)
                    else:
                        # Algorithm R: generate j in [0, i]
                        j=rng.rand_range(i+1)
                        if j < sample_size:
                            reservoir[j]=rec
                for rec in reservoir:
                    wtr.write_record(rec)
                return 0
        else:
            data=read_input_config(path)
            rdr=get_reader(data,args)
            headers=rdr.headers()
            if not args.get('no_headers',False):
                if len(headers)>0:
                    wtr.write_record(headers)
            if sample_size==0:
                return 0
            reservoir=[]
            for i, rec in enumerate(rdr.records()):
                if i < sample_size:
                    reservoir.append(rec)
                else:
                    j=rng.rand_range(i+1)
                    if j < sample_size:
                        reservoir[j]=rec
            for rec in reservoir:
                wtr.write_record(rec)
            return 0

