# Regex handling
def translate_regex(pat_str):
    # translate Rust specific syntax to Python
    out=[]
    i=0
    in_class=False
    while i<len(pat_str):
        c=pat_str[i]
        if c=='\\' and i+1<len(pat_str):
            nxt=pat_str[i+1]
            if nxt=='z':
                out.append('\\Z'); i+=2; continue
            # \p{...} handling later via error detection or simple translations
            out.append(c); out.append(nxt); i+=2; continue
        if c=='[' and not in_class:
            in_class=True; out.append(c); i+=1; continue
        if c==']' and in_class:
            in_class=False; out.append(c); i+=1; continue
        if not in_class and pat_str.startswith('(?<', i):
            # could be named group if next is not = or !
            if i+3<len(pat_str) and pat_str[i+3] not in ('=','!'):
                # find >
                j=pat_str.find('>', i+3)
                if j!=-1:
                    name=pat_str[i+3:j]
                    out.append('(?P<'+name+'>'); i=j+1; continue
            out.append(c); i+=1; continue
        out.append(c); i+=1
    return ''.join(out)

def rust_regex_error(pat_str, py_err):
    # Try to identify common Rust regex errors
    msg=None; span_start=0; span_len=1
    # invalid repetition range
    m=re.search(r'\{(\d+),(\d+)\}', pat_str)
    if m and int(m.group(1))>int(m.group(2)):
        msg="invalid repetition count range, the start must be <= the end"; span_start=m.start(); span_len=m.end()-m.start()
    elif pat_str.endswith('\\') and not pat_str.endswith('\\\\'):
        # trailing backslash: check count of trailing backslashes odd?
        # simple:
        cnt=len(pat_str)-len(pat_str.rstrip('\\'))
        if cnt%2==1:
            msg="incomplete escape sequence, reached end of pattern prematurely"; span_start=len(pat_str)-1; span_len=1
    if msg is None:
        # unclosed character class
        in_class=False; esc=False; class_start=None
        for idx,ch in enumerate(pat_str):
            if esc: esc=False; continue
            if ch=='\\': esc=True; continue
            if ch=='[' and not in_class: in_class=True; class_start=idx
            elif ch==']' and in_class: in_class=False
        if in_class:
            msg="unclosed character class"; span_start=class_start; span_len=1
    if msg is None:
        # unclosed group
        depth=0; last_open=-1; esc=False; in_class=False
        for idx,ch in enumerate(pat_str):
            if esc: esc=False; continue
            if ch=='\\': esc=True; continue
            if ch=='[': in_class=True
            elif ch==']': in_class=False
            elif not in_class and ch=='(': depth+=1; last_open=idx
            elif not in_class and ch==')':
                if depth>0: depth-=1
        if depth>0:
            msg="unclosed group"; span_start=last_open; span_len=1
    if msg is None:
        # invalid character class range
        m=re.search(r'\[([^\]])-([^\]])\]', pat_str)
        if m:
            # check range inside
            # naive find z-a pattern
            mm=re.search(r'(.)-(.)', pat_str)
            if mm and ord(mm.group(1))>ord(mm.group(2)):
                msg="invalid character class range, the start must be <= the end"; span_start=mm.start(); span_len=3
    if msg is None:
        # \p property
        m=re.search(r'\\p\{([^}]+)\}', pat_str)
        if m:
            msg="Unicode property not found"; span_start=m.start(); span_len=m.end()-m.start()
    if msg is None:
        # repetition missing expression at start or (?) etc
        if len(pat_str)>0 and pat_str[0] in '*+?':
            msg="repetition operator missing expression"; span_start=0; span_len=1
        elif '(?' in pat_str:
            # find (?) (?) pattern
            idx=pat_str.find('(?)')
            if idx!=-1:
                # Rust reports position of ? inside
                msg="repetition operator missing expression"; span_start=idx+2; span_len=1
    if msg is None:
        # fallback: use python message as error text (best effort)
        msg=str(py_err)
        span_start=getattr(py_err, 'pos', 0) or 0; span_len=1
    tildes='~'*79
    errtxt=f"Syntax(\n{tildes}\nregex parse error:\n    {pat_str}\n    {' '*span_start}{'^'*span_len}\nerror: {msg}\n{tildes}\n)"
    return CliError(errtxt.encode('utf-8','surrogateescape'))

def compile_search_regex(pat_str, ignore_case):
    translated=translate_regex(pat_str)
