# Statistics helpers
I64_MIN=-9223372036854775808; I64_MAX=9223372036854775807
def wrap_i64(v):
    v &= (1<<64)-1
    if v> I64_MAX: v-= (1<<64)
    return v

_float_re=re.compile(rb'^[+-]?((\d+(\.\d*)?)|(\.\d+))([eE][+-]?\d+)?$')
def parse_rust_i64(b):
    # bytes
    if len(b)==0: return None
    s=b
    if s[0:1] in (b'+',b'-'):
        digits=s[1:]
    else:
        digits=s
    if len(digits)==0 or not all(48<=c<=57 for c in digits): return None
    v=int(s.decode())
    if v<I64_MIN or v>I64_MAX: return None
    return v

def parse_rust_f64(b):
    if len(b)==0: return None
    low=b.lower()
    # inf/nan
    core=low
    sign=1.0
    if core.startswith(b'+'): core=core[1:]
    elif core.startswith(b'-'): core=core[1:]; sign=-1.0
    if core==b'inf' or core==b'infinity':
        return sign*math.inf
    if core==b'nan':
        return math.nan
    if not _float_re.match(b): return None
    try:
        return float(b.decode())
    except Exception:
        return None

def format_f64(x):
    if math.isnan(x): return "NaN"
    if math.isinf(x): return "inf" if x>0 else "-inf"
