        indices=list(range(len(headers)))
    else:
        indices=sel.resolve(headers, args.get('no_headers',False))
    rows=list(rdr.records())
    numeric=args.get('numeric',False); reverse_flag=args.get('reverse',False)
    def parse_f64(b):
        return parse_rust_f64(b)
    def cmp_rows(a,b):
        for idx in indices:
            av=a[idx]; bv=b[idx]
            if numeric:
                af=parse_f64(av); bf=parse_f64(bv)
                if af is None or bf is None:
                    # NaN semantics: treat as equal
                    continue
                if math.isnan(af) or math.isnan(bf):
                    continue
                if af<bf: return -1
                if af>bf: return 1
            else:
                if av<bv: return -1
                if av>bv: return 1
        return 0
    if reverse_flag:
        orig_cmp=cmp_rows
        def cmp_rows_rev(a,b):
            return -orig_cmp(a,b)
        rows.sort(key=functools.cmp_to_key(cmp_rows_rev))
    else:
        rows.sort(key=functools.cmp_to_key(cmp_rows))
    with OutCtx(args.get('output')) as stream:
        wtr=CsvWriter(stream, delimiter=args.get('delimiter',44))
        if not args.get('no_headers',False) and len(headers)>0:
            wtr.write_record(headers)
        for rec in rows:
            wtr.write_record(rec)
    return 0

