        err(b"--size must be greater than 0.")
    try:
        os.makedirs(B(outdir), exist_ok=True)
    except OSError as e:
        raise CliError(io_error_bytes(e))
    data=read_input_config(path)
    rdr=get_reader(data,args)
    headers=rdr.headers()
    no_headers=args.get('no_headers',False)
    # chunk management
    chunk_index=0  # start index of current chunk
    count_in_chunk=0
    cur_stream=None; cur_wtr=None
    def open_chunk(start_idx):
        nonlocal cur_stream, cur_wtr
        fname=template.replace('{}', str(start_idx),1)
        full=os.path.join(B(outdir), B(fname))
        parent=os.path.dirname(full)
        if parent and not os.path.exists(parent):
            try: os.makedirs(parent, exist_ok=True)
            except OSError as e: raise CliError(io_error_bytes(e))
        try:
            cur_stream=open(full,'wb')
        except OSError as e:
            raise CliError(io_error_bytes(e))
        cur_wtr=CsvWriter(cur_stream, delimiter=args.get('delimiter',44))
        if not no_headers:
            cur_wtr.write_record(headers)
    try:
        open_chunk(0)
        for rec in rdr.records():
            if count_in_chunk>=size:
                cur_stream.close()
                chunk_index+=size
                open_chunk(chunk_index)
                count_in_chunk=0
            cur_wtr.write_record(rec)
            count_in_chunk+=1
    finally:
        if cur_stream is not None:
            try: cur_stream.close()
            except Exception: pass
    return 0

