def main_error(msg_first):
    return CliError((msg_first+"\n\nUsage:\n"+MAIN_USAGE_SNIPPET.rstrip('\n')).encode())

def run_main(argv):
    # argv list of strings
    if len(argv)==0:
        sys.stderr.buffer.write(NO_ARGS_TEXT.encode()); return 0
    # special leading --
    if argv[0]=="--":
        if len(argv)==1:
            sys.stderr.buffer.write(NO_ARGS_TEXT.encode()); return 0
        cmd_candidate=argv[1]
        low=cmd_candidate.lower()
        if low in COMMANDS:
            raise CliError(f"xsv expects commands in lowercase. Did you mean '--'?".encode())
        else:
            raise CliError(f"Could not match '{low}' with any of the allowed variants: {COMMANDS}".encode())
    # parse leading flags
    flags={}; counts={}; pos_index=None; command=None; subargs=[]
    i=0
    main_longs={'list':('list',False),'help':('help',False),'version':('version',False)}
    main_shorts={'h':'help'}
    while i<len(argv):
        token=argv[i]
        if token=="--":
            # as separator for remaining; next is command
            if i+1<len(argv):
                command=argv[i+1]; subargs=argv[i+2:]; pos_index=i+1
            else:
                command=None
            break
        if token=="-" or token=="" or not token.startswith('-'):
            command=token; subargs=argv[i+1:]; pos_index=i; break
        if token.startswith('--'):
            if '=' in token:
                name,val=token.split('=',1)
                key=name[2:]
                if key not in main_longs:
                    # unknown
                    raise unknown_main_flag(name)
                raise CliError((f"Flag '{name}' cannot have an argument, but found '{val}'.\n\nUsage:\n"+MAIN_USAGE_SNIPPET.rstrip('\n')).encode())
            else:
                key=token[2:]
                if key not in main_longs:
                    raise unknown_main_flag(token)
                dest=main_longs[key][0]; counts[dest]=counts.get(dest,0)+1; flags[dest]=True
            i+=1; continue
        else:
            # short group
            j=1
            while j<len(token):
                c=token[j]
                if c not in main_shorts:
                    raise unknown_main_flag('-'+c)
                dest=main_shorts[c]; counts[dest]=counts.get(dest,0)+1; flags[dest]=True; j+=1
            i+=1; continue
    if any(c>1 for c in counts.values()):
        raise main_error("Invalid arguments.")
    if command is not None and flags:
        raise main_error("Invalid arguments.")
    if command is None:
        if flags.get('help'):
            sys.stdout.buffer.write(MAIN_HELP_DOCOPT.encode()); return 0
        if flags.get('version'):
            sys.stdout.buffer.write(b"0.13.0\n"); return 0
        if flags.get('list'):
            sys.stdout.buffer.write(LIST_TEXT.encode()); return 0
        sys.stderr.buffer.write(NO_ARGS_TEXT.encode()); return 0
    # command dispatch
    if command=="help":
        sys.stdout.buffer.write(MAIN_HELP.encode()); return 0
    low=command.lower()
    if command not in COMMANDS:
        if low in COMMANDS:
            raise CliError(f"xsv expects commands in lowercase. Did you mean '{low}'?".encode())
        raise CliError(f"Could not match '{low}' with any of the allowed variants: {COMMANDS}".encode())
    spec=SPECS[command]
    parsed=parse_subcommand(spec, subargs)
    args=dict(parsed.opts)
    for k,v in parsed.pos_values.items():
        args[f'_pos{k}']=v
    func=CMD_FUNCS[command]
    return func(args, parsed.positionals)

def unknown_main_flag(flag):
    msg=f"Unknown flag: '{flag}'"
    if flag.startswith('--'):
        bare=flag[2:]
        cands=['list','help','version']
        best=None; bestd=None
        for cand in cands:
            d=levenshtein(bare,cand)
            if bestd is None or d<bestd: bestd=d; best=cand
        if best is not None and bestd<=2:
            msg+=f". Did you mean '--{best}'?"
    return CliError((msg+"\n\nUsage:\n"+MAIN_USAGE_SNIPPET.rstrip('\n')).encode())

def main():
    try:
        code=run_main(sys.argv[1:])
    except CliError as e:
        # flush stdout
        try: sys.stdout.buffer.flush()
        except Exception: pass
        msg=e.msg
        sys.stderr.buffer.write(msg)
        if not msg.endswith(b'\n'):
            sys.stderr.buffer.write(b'\n')
        try: sys.stderr.buffer.flush()
        except Exception: pass
        return 1
    except BrokenPipeError:
        return 1
    return code or 0

if __name__=='__main__':
    sys.exit(main())
