   mean+=d/n; m2+=d*(x-mean); outvar=m2/n
  elif name=='runvarF':
   mean+=d/n; var=var+(d*(x-mean)-var)/n; outvar=var
  elif name=='runvar_weighted':
   mean+=d/n; var=((n-1)*var + d*(x-mean))/n; outvar=var
  elif name=='delta_sq_scaled':
   mean+=d/n; m2+=d*d*(n-1)/n; outvar=m2/n
  elif name=='m2_mean_weighted':
