import subprocess, itertools
def mode(counts):
 vals=[]
 for v,c in zip("abcde",counts): vals += [v]*c
 inp="x\n"+"\n".join(vals)+"\n"; p=subprocess.run(["/workspace/executable","stats","--mode"],input=inp.encode(),capture_output=True)
 return p.stdout.decode().strip().split("\n")[1].rsplit(",",1)[-1]
# gather triples
obs={}
for counts in itertools.product(range(1,5), repeat=3):
 obs[counts]=mode(counts)
# candidate algorithms on sorted list
def expand(counts):
 out=[]
 for v,c in zip("abcde",counts): out += [v]*c
 return out
def bm_sorted(counts, final_rule):
 v=expand(counts); cand=None; cnt=0
 for x in v:
  if cnt==0: cand=x; cnt=1
  elif cand==x: cnt+=1
  else: cnt-=1
 if final_rule=='cand': return cand
 if final_rule=='cand_if_cntpos': return cand if cnt>0 else 'N/A'
 if final_rule=='cand_if_actual_gt1':
  return cand if counts["abcde".index(cand)]>1 else 'N/A'
 if final_rule=='cand_if_cnt_or_actual':
  return cand if (cnt>0 or counts["abcde".index(cand)]>1) else 'N/A'
for rule in ['cand','cand_if_cntpos','cand_if_actual_gt1','cand_if_cnt_or_actual']:
 score=sum(1 for k,o in obs.items() if bm_sorted(k,rule)==o)
 print(rule,score,'/',len(obs))
 # print mismatches for best
 if score>20:
  for k,o in obs.items():
   if bm_sorted(k,rule)!=o: print(" mismatch",k,o,"pred",bm_sorted(k,rule))
